class Ledger:
    def __init__(self):
        self.balances = {}
        self.seen = {}
    def apply(self, events):
        if not isinstance(events, list):
            raise ValueError("events must be a list")

        # Stage changes so any invalid event leaves the ledger untouched.
        balances = self.balances.copy()
        seen = self.seen.copy()
        for event in events:
            if not isinstance(event, dict):
                raise ValueError("each event must be a dictionary")
            identifier = event.get("id")
            account = event.get("account")
            amount = event.get("amount")
            if not isinstance(identifier, str) or not identifier:
                raise ValueError("id must be a nonempty string")
            if not isinstance(account, str) or not account:
                raise ValueError("account must be a nonempty string")
            if not isinstance(amount, int) or isinstance(amount, bool):
                raise ValueError("amount must be an integer, excluding bool")

            transaction = (account, amount)
            if identifier in seen:
                if seen[identifier] != transaction:
                    raise ValueError("conflicting reuse of event id")
                continue
            balances[account] = balances.get(account, 0) + amount
            seen[identifier] = transaction

        self.balances = balances
        self.seen = seen
        return balances.copy()

def normalize_intervals(intervals):
    """Validate and merge overlapping half-open integer intervals."""
    try:
        iterator = iter(intervals)
    except TypeError as exc:
        raise ValueError("intervals must be iterable") from exc

    validated = []
    for pair in iterator:
        try:
            start, end = pair
        except (TypeError, ValueError) as exc:
            raise ValueError("each interval must have exactly two endpoints") from exc
        if (not isinstance(start, int) or isinstance(start, bool)
                or not isinstance(end, int) or isinstance(end, bool)):
            raise ValueError("endpoints must be integers, excluding bool")
        if start > end:
            raise ValueError("interval start must not exceed its end")
        if start < end:
            validated.append((start, end))

    validated.sort()
    merged = []
    for start, end in validated:
        if merged and start < merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged

def normalize_intervals(intervals):
    """Validate and merge overlapping half-open intervals, preserving adjacency."""
    try:
        iterator = iter(intervals)
    except TypeError as exc:
        raise ValueError("intervals must be iterable") from exc

    validated = []
    for pair in iterator:
        try:
            start, end = pair
        except (TypeError, ValueError) as exc:
            raise ValueError("each interval must contain exactly two endpoints") from exc
        if any(not isinstance(value, int) or isinstance(value, bool)
               for value in (start, end)):
            raise ValueError("endpoints must be integers, excluding bool")
        if start > end:
            raise ValueError("interval start must not exceed its end")
        if start != end:
            validated.append((start, end))

    validated.sort()
    merged = []
    for start, end in validated:
        if merged and start < merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged
